const DEFAULT_STATE={status:'Provisional',events:[
 {id:'open',name:'Open',detail:'Tournament',visible:true},
 {id:'women',name:'Women',detail:'Tournament',visible:true},
 {id:'groms',name:'Groms',detail:'Tournament',visible:true},
 {id:'infinity',name:'Infinity Race',detail:'Mass race',visible:true},
 {id:'surf',name:'Surf & Dirt',detail:'Mass race',visible:true},
 {id:'legends',name:'Legends',detail:'Race',visible:true},
 {id:'chair',name:'Chair Race',detail:'Race',visible:true},
 {id:'relay',name:'2 Hour Relay Race',detail:'Relay race',visible:true}
]};

const FIRST_NAMES={
 open:['Luca','Noah','Mikael','Theo','Jack','Tomas','Marco','Oliver','Ben','Hugo','Oscar','Leo','Felix','Rory','Elias','Max','Louis','Finn','Anton','Samuel','Jonas','Alex','Nico','George','Daniel','Tom','Jamie','Milo','Arthur','Kai','Lewis','Pedro'],
 women:['Amelia','Sofia','Lea','Freja','Maya','Isla','Eva','Alice','Clara','Nora','Lily','Mia','Ella','Zoe','Ruby','Anna','Emilia','Chloe','Lucy','Ivy','Sara','Lola','Grace','Elsa','Millie','Olivia','Ines','Eva','Sienna','Layla','Julia','Marta'],
 groms:['Finn','Alex','Jamie','Taylor','Charlie','Robin','Sam','Riley','Casey','Morgan','Avery','Sky','Max','Leo','Mia','Zoe','Noah','Ella','Kai','Ruby','Milo','Ivy','Ben','Lily','Theo','Clara','Oscar','Nora','Hugo','Maya','Jack','Sofia']
};
const LAST_NAMES=['Moretti','Williams','Sorensen','Martin','Turner','Novak','Bianchi','Hansen','Carter','Dubois','Rossi','Evans','Larsen','Silva','Walker','Brown','Muller','Jensen','Taylor','Costa','Andersson','Wilson','Pereira','Clark','Berg','Fischer','Lewis','Garcia','Murphy','Schmidt','King','Reed'];
const COUNTRIES=['ITA','GBR','DNK','FRA','GBR','CZE','ITA','DNK','GBR','FRA','ITA','GBR','DNK','PRT','GBR','GBR','DEU','DNK','GBR','PRT','SWE','GBR','PRT','GBR','NOR','DEU','GBR','ESP','IRL','DEU','GBR','GBR'];
const TOURNAMENT_STAGES=[
 {id:'qualifiers',label:'Qualifiers',count:1,size:32,prefix:'Qualifying'},
 {id:'heats',label:'Heats',count:8,size:32,prefix:'Heat'},
 {id:'quarters',label:'Quarter-finals',count:4,size:16,prefix:'Quarter-final'},
 {id:'semis',label:'Semi-finals',count:2,size:8,prefix:'Semi-final'},
 {id:'final',label:'Final',count:1,size:4,prefix:'Final'}
];
function appState(){try{const saved=JSON.parse(localStorage.getItem('owar-demo-state-v5')||'{}');const events=DEFAULT_STATE.events.map(base=>({...base,...(saved.events||[]).find(e=>e.id===base.id),name:base.name}));return {...DEFAULT_STATE,...saved,events}}catch{return DEFAULT_STATE}}
function saveState(s){localStorage.setItem('owar-demo-state-v5',JSON.stringify(s));window.dispatchEvent(new Event('owar-update'))}
function escapeHtml(v){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function eventById(id){return appState().events.find(e=>e.id===id)||appState().events[0]}
function roster(eventId){const pool=FIRST_NAMES[eventId]||FIRST_NAMES.open;return Array.from({length:32},(_,i)=>({id:`${eventId}-${i+1}`,bib:String((eventId==='women'?40:eventId==='groms'?10:100)+i),name:`${pool[i]} ${LAST_NAMES[(i+(eventId==='women'?7:eventId==='groms'?13:0))%LAST_NAMES.length]}`,country:COUNTRIES[(i+(eventId==='women'?5:eventId==='groms'?9:0))%COUNTRIES.length],seed:i+1}))}
function pad(n,w=2){return String(n).padStart(w,'0')}
function timeMs(rider,stageIndex,raceIndex){return 95500+(rider.seed*427)+(stageIndex*1189)+(raceIndex*173)+((rider.seed*stageIndex*97)%811)}
function formatTime(ms){const min=Math.floor(ms/60000),sec=Math.floor((ms%60000)/1000),milli=ms%1000;return `${pad(min)}:${pad(sec)}.${pad(milli,3)}`}
function stagesFor(eventId){if(['open','women','groms'].includes(eventId))return TOURNAMENT_STAGES;return [{id:'final',label:'Results',count:1,size:16,prefix:eventById(eventId).name}]}
function racesFor(eventId,stage){const riders=roster(eventId).slice(0,stage.size);if(stage.id==='qualifiers')return [{name:'Qualifying order',riders}];const groups=Array.from({length:stage.count},(_,i)=>({name:stage.count===1?stage.prefix:`${stage.prefix} ${i+1}`,riders:[]}));riders.forEach((r,i)=>groups[i%stage.count].riders.push(r));return groups}
function resultRows(eventId,stage,race,raceIndex){const stageIndex=stagesFor(eventId).findIndex(s=>s.id===stage.id);return race.riders.map(r=>({...r,ms:timeMs(r,stageIndex,raceIndex)})).sort((a,b)=>a.ms-b.ms)}
function riderUrl(eventId,riderId){return `/rider/?event=${encodeURIComponent(eventId)}&id=${encodeURIComponent(riderId)}`}
function tableMarkup(eventId,stage,race,raceIndex){const rows=resultRows(eventId,stage,race,raceIndex);return `<article class="race-table"><header><div><span>${escapeHtml(stage.label)}</span><h3>${escapeHtml(race.name)}</h3></div><b>${rows.length} riders</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Rider</th><th>Time</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="${i<3?'podium':''}"><td class="place">${i+1}</td><td><a class="rider rider-link" href="${riderUrl(eventId,r.id)}"><span class="bib">${escapeHtml(r.bib)}</span><span><span class="name">${escapeHtml(r.name)}</span><span class="country">${escapeHtml(r.country)}</span></span></a></td><td class="time">${formatTime(r.ms)}${i?` <span class="gap">+${((r.ms-rows[0].ms)/1000).toFixed(3)}</span>`:''}</td></tr>`).join('')}</tbody></table></div></article>`}

function publicPage(){const tabs=document.querySelector('#event-tabs'),rounds=document.querySelector('#round-nav'),results=document.querySelector('#stage-results'),title=document.querySelector('#race-title'),summary=document.querySelector('#result-count'),badge=document.querySelector('#status-badge');const requested=new URLSearchParams(location.search).get('event');let current=requested||'open';let activeStages={};
 const render=()=>{const s=appState(),shown=s.events.filter(e=>e.visible);badge.textContent=s.status;if(!shown.some(e=>e.id===current))current=shown[0]?.id||null;tabs.innerHTML=shown.map(e=>`<button class="tab ${e.id===current?'active':''}" data-id="${e.id}">${escapeHtml(e.name)}</button>`).join('');tabs.querySelectorAll('button').forEach(b=>b.onclick=()=>{current=b.dataset.id;render()});const ev=shown.find(e=>e.id===current);if(!ev){title.textContent='Results unavailable';rounds.innerHTML='';results.innerHTML='<div class="empty">No events are currently published.</div>';return}const stages=stagesFor(ev.id);const stageId=activeStages[ev.id]||stages[0].id;const stage=stages.find(x=>x.id===stageId)||stages[0];activeStages[ev.id]=stage.id;title.textContent=ev.name;rounds.innerHTML=stages.map((x,i)=>`<button class="round ${x.id===stage.id?'active':''}" data-stage="${x.id}"><span class="round-step">${pad(i+1)}</span><span class="round-name">${escapeHtml(x.label)}</span><small>${x.count} ${x.count===1?'table':'tables'}</small></button>`).join('');rounds.querySelectorAll('button').forEach(b=>b.onclick=()=>{activeStages[ev.id]=b.dataset.stage;render()});const races=racesFor(ev.id,stage);summary.textContent=stage.id==='qualifiers'?`${stage.size} riders · fastest first`:`${races.length} ${races.length===1?'race':'races'} in this round`;results.innerHTML=`<div class="race-grid ${races.length===1?'single':''}">${races.map((race,i)=>tableMarkup(ev.id,stage,race,i)).join('')}</div><div class="note stage-note">Select any rider to see every recorded time and the race it came from.</div>`};render();window.addEventListener('storage',render);window.addEventListener('owar-update',render)}

function riderPage(){const params=new URLSearchParams(location.search),eventId=params.get('event')||'men',riderId=params.get('id')||`${eventId}-1`,event=eventById(eventId),rider=roster(eventId).find(r=>r.id===riderId)||roster(eventId)[0],history=[];stagesFor(eventId).forEach((stage,stageIndex)=>{if(rider.seed>stage.size)return;racesFor(eventId,stage).forEach((race,raceIndex)=>{if(!race.riders.some(r=>r.id===rider.id))return;const rows=resultRows(eventId,stage,race,raceIndex),pos=rows.findIndex(r=>r.id===rider.id)+1;history.push({stage:stage.label,race:race.name,time:formatTime(timeMs(rider,stageIndex,raceIndex)),position:pos,field:rows.length})})});document.title=`${rider.name} · OWAR 2026`;document.querySelector('#rider-name').textContent=rider.name;document.querySelector('#rider-meta').textContent=`Bib ${rider.bib} · ${rider.country} · ${event.name}`;document.querySelector('#rider-bib').textContent=rider.bib;document.querySelector('#rider-event').textContent=event.name;document.querySelector('#race-total').textContent=history.length;document.querySelector('#best-time').textContent=history.reduce((best,x)=>!best||x.time<best?x.time:best,'');document.querySelector('#history-body').innerHTML=history.map(x=>`<tr><td><span class="history-stage">${escapeHtml(x.stage)}</span></td><td><strong>${escapeHtml(x.race)}</strong></td><td>${x.position} / ${x.field}</td><td class="time">${x.time}</td></tr>`).join('');document.querySelector('#back-results').href=`/?event=${encodeURIComponent(eventId)}`}

function adminPage(){const list=document.querySelector('#event-list'),status=document.querySelector('#event-status'),toast=document.querySelector('#toast');let s=appState();const render=()=>{list.innerHTML=s.events.map((e,i)=>`<div class="event-row"><div class="drag" aria-hidden="true">⋮⋮</div><div><h3>${escapeHtml(e.name)}</h3><p>${escapeHtml(e.detail)} · ${e.visible?'Visible publicly':'Hidden'}</p></div><label class="switch"><input type="checkbox" data-i="${i}" ${e.visible?'checked':''} aria-label="Show ${escapeHtml(e.name)}"><span class="slider"></span></label></div>`).join('');list.querySelectorAll('input').forEach(x=>x.onchange=()=>{s.events[+x.dataset.i].visible=x.checked;saveState(s);render();flash('Public visibility updated')})};status.value=s.status;status.onchange=()=>{s.status=status.value;saveState(s);flash(`Status changed to ${s.status}`)};document.querySelector('#simulate').onclick=()=>flash('New file imported · 2 seconds ago');document.querySelector('#reset').onclick=()=>{s=JSON.parse(JSON.stringify(DEFAULT_STATE));saveState(s);status.value=s.status;render();flash('Demo settings reset')};function flash(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}render()}

if(document.body.dataset.page==='public')publicPage();
if(document.body.dataset.page==='rider')riderPage();
if(document.body.dataset.page==='admin')adminPage();
